from pathlib import Path
import re

# recommend.js: preset members are required inclusions, never positional locks.
p = Path('js/recommend.js')
text = p.read_text(encoding='utf-8')
text = re.sub(r'from "\.\/score\.js\?v=[^"]+";', 'from "./score.js?v=20260813.1";', text, count=1)
old = '''function composeMemberSlots(currentMembers, lockedSlots, fill) {\n  const available = [...fill];\n  return currentMembers.slice(1, 6).map((cardId, index) => {\n    if (lockedSlots[index + 1] && cardId) return cardId;\n    return available.shift()?.id ?? null;\n  });\n}\n'''
new = '''function composeMemberIds(requiredMemberIds, fill) {\n  return [...requiredMemberIds, ...fill.map((card) => card.id)];\n}\n'''
if old not in text:
    raise SystemExit('composeMemberSlots pattern not found')
text = text.replace(old, new, 1)
text = text.replace(
    'const memberSlotIds = composeMemberSlots(currentMembers, locked, fill);',
    'const memberSlotIds = composeMemberIds(fixedMemberIdList, fill);',
    1,
)
text = text.replace(
    'const score = evaluateDeck({ leader, members, music, difficulty, playMode, separateRole });',
    'const score = evaluateDeck({ leader, members, music, difficulty, playMode, separateRole, evaluationTarget: normalizedSimulationTarget });',
    1,
)
p.write_text(text, encoding='utf-8')

# score.js: cache song constants, selectively evaluate search target, and expose reusable composition base.
p = Path('js/score.js')
text = p.read_text(encoding='utf-8')
text = re.sub(r'from "\.\/chart-score\.js\?v=[^"]+";', 'from "./chart-score.js?v=20260813.1";', text, count=1)
marker = 'const UNIT_CONTEXT = Object.freeze({ duration: 110, notes: 800, coefficient: 5, kind: "unit" });\n'
if marker not in text:
    raise SystemExit('UNIT_CONTEXT marker not found')
text = text.replace(marker, marker + '''const COMBO_AVERAGE_CACHE = new Map();\nconst GENERIC_CONTEXT_CACHE = new Map();\nconst MUSIC_CONTEXT_CACHE = new WeakMap();\nconst SONG_KERNEL_CACHE = new WeakMap();\n''', 1)

start = text.index('function contextFromMusic(')
end = text.index('function songSkillMultiplier(', start)
replacement = '''function contextFromMusic(music, difficulty) {\n  const normalizedDifficulty = String(difficulty ?? "EXPERT").toUpperCase();\n  if (music) {\n    let cache = MUSIC_CONTEXT_CACHE.get(music);\n    if (!cache) {\n      cache = new Map();\n      MUSIC_CONTEXT_CACHE.set(music, cache);\n    }\n    if (cache.has(normalizedDifficulty)) return cache.get(normalizedDifficulty);\n    const context = buildSongContext(music, normalizedDifficulty, music?._chart ?? null);\n    const resolved = { ...context, comboMultiplier: averageComboMultiplier(context.notes) };\n    cache.set(normalizedDifficulty, resolved);\n    return resolved;\n  }\n  if (GENERIC_CONTEXT_CACHE.has(normalizedDifficulty)) return GENERIC_CONTEXT_CACHE.get(normalizedDifficulty);\n  const density = DIFFICULTY_NOTE_DENSITY[normalizedDifficulty] ?? DIFFICULTY_NOTE_DENSITY.EXPERT;\n  const resolved = {\n    ...UNIT_CONTEXT,\n    kind: "generic",\n    comboMultiplier: averageComboMultiplier(UNIT_CONTEXT.notes),\n    density,\n    title: "범용 악곡",\n    chartAccuracy: "generic",\n    noteTimeline: [],\n    skillTimeline: [],\n    fever: null,\n  };\n  GENERIC_CONTEXT_CACHE.set(normalizedDifficulty, resolved);\n  return resolved;\n}\n\nfunction averageComboMultiplier(noteCount) {\n  const notes = Math.max(1, Math.round(finite(noteCount, 1)));\n  if (COMBO_AVERAGE_CACHE.has(notes)) return COMBO_AVERAGE_CACHE.get(notes);\n  let before = 0;\n  let after = 0;\n  for (let note = 1; note <= notes; note += 1) {\n    before += 1 + Math.min(10, Math.floor((note - 1) / 100)) / 100;\n    after += 1 + Math.min(10, Math.floor(note / 100)) / 100;\n  }\n  const value = (before + after) / (2 * notes);\n  COMBO_AVERAGE_CACHE.set(notes, value);\n  return value;\n}\n\nfunction cachedSongKernel(context, playMode, scoreRules) {\n  let cache = SONG_KERNEL_CACHE.get(context);\n  if (!cache) {\n    cache = new Map();\n    SONG_KERNEL_CACHE.set(context, cache);\n  }\n  const key = `${playMode === "manual" ? "manual" : "auto"}|${scoreRules?.source_commit ?? "default"}`;\n  if (!cache.has(key)) cache.set(key, songKernel(context, playMode, scoreRules));\n  return cache.get(key);\n}\n\n'''
text = text[:start] + replacement + text[end:]

start = text.index('function projectSong(')
end = text.index('function diagnostics(', start)
replacement = '''function projectSong(unitScore, members, music, difficulty, fullSupportPct, playMode = "auto", evaluationTarget = "both") {\n  if (!music) return null;\n  const selected = contextFromMusic(music, difficulty);\n  const generic = contextFromMusic(null, difficulty);\n  const scoreRules = music?._scoreRules ?? null;\n  const genericExpected = songSkillMultiplier(members, generic, fullSupportPct);\n  const needExpected = evaluationTarget !== "potential";\n  const needMaximum = evaluationTarget !== "score";\n  if (selected.chartAccuracy === "exact" && selected.noteTimeline.length) {\n    return timelineSongProjection({\n      unitScore,\n      members,\n      context: selected,\n      genericContext: generic,\n      fullSupportPct,\n      playMode,\n      genericSkillMultiplier: genericExpected.skillMultiplier,\n      scoreRules,\n      evaluationTarget,\n    });\n  }\n  const selectedExpected = needExpected ? songSkillMultiplier(members, selected, fullSupportPct) : null;\n  const selectedMaximum = needMaximum ? songSkillMultiplier(members, selected, fullSupportPct, true) : null;\n  const manual = playMode === "manual";\n  const selectedKernel = cachedSongKernel(selected, playMode, scoreRules);\n  const genericKernel = cachedSongKernel(generic, playMode, scoreRules);\n  const baseRatio = genericKernel > 0 ? selectedKernel / genericKernel : 1;\n  const skillRatio = selectedExpected && genericExpected.skillMultiplier > 0\n    ? selectedExpected.skillMultiplier / genericExpected.skillMultiplier\n    : 1;\n  const maxSkillRatio = selectedMaximum && genericExpected.skillMultiplier > 0\n    ? selectedMaximum.skillMultiplier / genericExpected.skillMultiplier\n    : 1;\n  const averageScore = selectedExpected\n    ? Math.max(0, Math.round(unitScore * baseRatio * skillRatio))\n    : null;\n  const rawMaxScore = selectedMaximum\n    ? Math.max(0, Math.round(unitScore * baseRatio * maxSkillRatio))\n    : null;\n  const maxScore = rawMaxScore == null ? null : Math.max(averageScore ?? 0, rawMaxScore);\n  return {\n    averageScore,\n    maxScore,\n    baseRatio,\n    skillRatio,\n    maxSkillRatio,\n    context: selected,\n    playMode: manual ? "manual" : "auto",\n    expected: selectedExpected,\n    maximum: selectedMaximum,\n    specialWindows: [],\n    note: selected.chartAccuracy === "master"\n      ? "Master의 실제 풀콤보 노트 수를 사용하고, SP 타이밍은 집계 기반으로 근사합니다."\n      : manual\n        ? "Manual FC 근사: 추정 노트와 콤보 보너스를 포함합니다."\n        : "AUTO 근사: 추정 노트 수를 사용하고 콤보 보너스를 제외합니다.",\n  };\n}\n\n'''
text = text[:start] + replacement + text[end:]

start = text.index('export function evaluateDeck({')
end = text.index('export function memberIntrinsicValue(', start)
replacement = '''function buildDeckComposition({ leader, members, separateRole = true, includePotential = true }) {\n  if (!leader || members.length !== 5 || members.some((member) => !member)) return null;\n  if (separateRole && members.some((member) => member.characterId === leader.characterId)) return null;\n  if (!allConditionsMet(leader.leader.primaryCondition, members)) return null;\n\n  const baseStats = members.reduce((total, member) => ({\n    p: total.p + member.stats.p,\n    t: total.t + member.stats.t,\n    s: total.s + member.stats.s,\n  }), { p: 0, t: 0, s: 0 });\n  const passive = passiveEvaluation(members);\n  const leaderEffects = { p: 0, t: 0, s: 0, support: 0 };\n  addEffects(leaderEffects, leader.leader.primaryEffects);\n  const additionalMet = allConditionsMet(leader.leader.additionalCondition, members);\n  if (additionalMet) addEffects(leaderEffects, leader.leader.additionalEffects);\n  const leaderBonusStats = {\n    p: baseStats.p * leaderEffects.p / 100,\n    t: baseStats.t * leaderEffects.t / 100,\n    s: baseStats.s * leaderEffects.s / 100,\n  };\n  const preEnhancementStats = {\n    p: baseStats.p + leaderBonusStats.p + passive.bonusStats.p,\n    t: baseStats.t + leaderBonusStats.t + passive.bonusStats.t,\n    s: baseStats.s + leaderBonusStats.s + passive.bonusStats.s,\n  };\n  const enhancementRate = members.reduce((sum, member) => sum + member.enhancementPermyriad, 0) / 10000;\n  const deckStats = {\n    p: Math.round(preEnhancementStats.p * (1 + enhancementRate)),\n    t: Math.round(preEnhancementStats.t * (1 + enhancementRate)),\n    s: Math.round(preEnhancementStats.s * (1 + enhancementRate)),\n  };\n  const baseParameter = baseStats.p + baseStats.t + baseStats.s;\n  const leaderPower = leaderBonusStats.p + leaderBonusStats.t + leaderBonusStats.s;\n  const passivePower = passive.bonusStats.p + passive.bonusStats.t + passive.bonusStats.s;\n  const overallPower = deckStats.p + deckStats.t + deckStats.s;\n  const enhancementPower = Math.max(0, Math.round(overallPower - baseParameter - leaderPower - passivePower));\n\n  const unitSkill = skillEvaluation(members, UNIT_CONTEXT, true);\n  const active = unitSkill.active.correctedPct;\n  const activeBase = unitSkill.activeBase.correctedPct;\n  const rateGain = Math.max(0, active - activeBase);\n  const scoreBonusDetail = {\n    outfit: round1(active * leaderEffects.support / 100),\n    active: round1(active),\n    board: 0,\n    passive: round1(active * passive.supportPoints / 100),\n    special: round1(activeBase * unitSkill.special.supportAveragePct / 100 + rateGain),\n  };\n  const scoreBonusPct = round1(Object.values(scoreBonusDetail).reduce((sum, value) => sum + value, 0));\n  const unitScore = unitScoreFromDisplayed(overallPower, scoreBonusPct);\n\n  let potentialUnitScore = unitScore;\n  let potentialScoreBonusPct = scoreBonusPct;\n  if (includePotential) {\n    const potentialUnitSkill = skillEvaluation(members, UNIT_CONTEXT, true, true);\n    const potentialActive = potentialUnitSkill.active.correctedPct;\n    const potentialActiveBase = potentialUnitSkill.activeBase.correctedPct;\n    const potentialRateGain = Math.max(0, potentialActive - potentialActiveBase);\n    const potentialScoreBonusDetail = {\n      outfit: round1(potentialActive * leaderEffects.support / 100),\n      active: round1(potentialActive),\n      board: 0,\n      passive: round1(potentialActive * passive.supportPoints / 100),\n      special: round1(potentialActiveBase * potentialUnitSkill.special.supportAveragePct / 100 + potentialRateGain),\n    };\n    potentialScoreBonusPct = round1(Object.values(potentialScoreBonusDetail).reduce((sum, value) => sum + value, 0));\n    potentialUnitScore = Math.max(unitScore, unitScoreFromDisplayed(overallPower, potentialScoreBonusPct));\n  }\n\n  return {\n    potentialComputed: includePotential,\n    baseStats,\n    passive,\n    leaderEffects,\n    additionalMet,\n    deckStats,\n    baseParameter,\n    leaderPower,\n    passivePower,\n    overallPower,\n    enhancementPower,\n    unitSkill,\n    active,\n    activeBase,\n    rateGain,\n    scoreBonusDetail,\n    scoreBonusPct,\n    unitScore,\n    potentialUnitScore,\n    potentialScoreBonusPct,\n    fullSupportPct: leaderEffects.support + passive.supportPoints,\n  };\n}\n\nexport function prepareDeckComposition({ leader, members, separateRole = true }) {\n  return buildDeckComposition({ leader, members, separateRole, includePotential: true });\n}\n\nexport function evaluateDeck({\n  leader,\n  members,\n  music = null,\n  difficulty = "EXPERT",\n  playMode = "auto",\n  separateRole = true,\n  includeDiagnostics = false,\n  evaluationTarget = "both",\n  preparedComposition = null,\n}) {\n  const needPotential = evaluationTarget !== "score";\n  let composition = preparedComposition;\n  if (!composition || (needPotential && !composition.potentialComputed)) {\n    composition = buildDeckComposition({ leader, members, separateRole, includePotential: needPotential });\n  }\n  if (!composition) return null;\n\n  const songProjection = projectSong(\n    composition.unitScore,\n    members,\n    music,\n    difficulty,\n    composition.fullSupportPct,\n    playMode,\n    evaluationTarget,\n  );\n  const rankingScore = songProjection?.averageScore ?? composition.unitScore;\n  const potentialRankingScore = songProjection?.maxScore ?? composition.potentialUnitScore;\n  const diagnosticContext = songProjection?.context ?? UNIT_CONTEXT;\n\n  return {\n    rankingScore,\n    potentialRankingScore,\n    unitScore: composition.unitScore,\n    potentialUnitScore: composition.potentialUnitScore,\n    estimatedSongScore: songProjection?.averageScore ?? null,\n    estimatedSongMax: songProjection?.maxScore ?? null,\n    songProjection,\n    deckStats: composition.deckStats,\n    baseStats: composition.baseStats,\n    overallPower: composition.overallPower,\n    scoreBonusPct: composition.scoreBonusPct,\n    potentialScoreBonusPct: composition.potentialScoreBonusPct,\n    activeScoreBonus: composition.active,\n    activeBaseScoreBonus: composition.activeBase,\n    activationRateGain: composition.rateGain,\n    supportPct: composition.fullSupportPct + composition.unitSkill.special.supportAveragePct,\n    activePassives: composition.passive.activeStates.filter((row) => row.active).length,\n    songKernelRatio: songProjection?.baseRatio ?? 1,\n    context: diagnosticContext,\n    leaderCondition: {\n      primaryMet: true,\n      primaryCount: leader.leader.primaryCondition.length,\n      additionalMet: composition.additionalMet,\n      additionalCount: leader.leader.additionalCondition.length,\n    },\n    detail: {\n      power: {\n        memberParameter: composition.baseParameter,\n        outfit: Math.round(composition.leaderPower),\n        board: 0,\n        passive: Math.round(composition.passivePower),\n        memory: 0,\n        enhancement: composition.enhancementPower,\n      },\n      scoreBonus: composition.scoreBonusDetail,\n      collision: {\n        groups: composition.unitSkill.active.duplicateGroups,\n        lossPct: round1(composition.unitSkill.active.collisionLossPct),\n      },\n    },\n    passiveStates: composition.passive.activeStates,\n    diagnostics: includeDiagnostics\n      ? diagnostics(members, diagnosticContext, composition.passive.activeStates, leader, composition.additionalMet)\n      : [],\n  };\n}\n\n'''
text = text[:start] + replacement + text[end:]
p.write_text(text, encoding='utf-8')

# chart-score.js: cache note weights and sweep active windows.
p = Path('js/chart-score.js')
text = p.read_text(encoding='utf-8')
marker = 'const DEFAULT_COMBO = Object.freeze(Array.from({ length: 11 }, (_, index) => ({ from: index * 100, scoreUpPct: index })));\n'
if marker not in text:
    raise SystemExit('chart-score DEFAULT_COMBO marker not found')
text = text.replace(marker, marker + 'const TIMELINE_WEIGHT_CACHE = new WeakMap();\n', 1)
text = text.replace(
    'return 1 - events.reduce((none, event) => none * (1 - clamp(finite(event.probability), 0, 1)), 1);',
    'return 1 - [...events].reduce((none, event) => none * (1 - clamp(finite(event.probability), 0, 1)), 1);',
    1,
)
marker = 'function memberMatchesCondition(member, condition) {'
insert = '''function timelineWeights(context, playMode, scoreRules) {\n  let cache = TIMELINE_WEIGHT_CACHE.get(context);\n  if (!cache) {\n    cache = new Map();\n    TIMELINE_WEIGHT_CACHE.set(context, cache);\n  }\n  const key = `${playMode === "manual" ? "manual" : "auto"}|${scoreRules?.source_commit ?? "default"}`;\n  if (cache.has(key)) return cache.get(key);\n  const manual = playMode === "manual";\n  const weights = (context.noteTimeline ?? []).map((note, index) => (\n    noteWeight(note?.[0], playMode, scoreRules)\n      * (manual ? comboMultiplier(index + 1, scoreRules) : 1)\n  ));\n  const result = { weights, baseWeight: weights.reduce((sum, value) => sum + value, 0) };\n  cache.set(key, result);\n  return result;\n}\n\n'''
if marker not in text:
    raise SystemExit('memberMatchesCondition marker not found')
text = text.replace(marker, insert + marker, 1)
start = text.index('function timelineSkillEvaluation(')
end = text.index('export function buildSongContext(', start)
replacement = '''function timelineSkillEvaluation(members, context, fullSupportPct, playMode, scoreRules, maximize = false) {\n  const windows = specialWindows(members, context);\n  const checks = buildActiveChecks(members, context, windows, maximize);\n  const notes = context.noteTimeline ?? [];\n  const scoring = timelineWeights(context, playMode, scoreRules);\n  let skillWeight = 0;\n  const coverageAcc = new Map(members.map((member) => [member.id, 0]));\n  const starts = [...checks.all].sort((left, right) => finite(left.time) - finite(right.time));\n  const ends = [...checks.all].sort((left, right) => finite(left.end) - finite(right.end));\n  const active = new Set();\n  const activeByMember = new Map(members.map((member) => [member.id, new Set()]));\n  let startIndex = 0;\n  let endIndex = 0;\n\n  notes.forEach((note, index) => {\n    const time = finite(note?.[1]);\n    while (endIndex < ends.length && finite(ends[endIndex].end) <= time + 1e-9) {\n      const row = ends[endIndex];\n      active.delete(row);\n      activeByMember.get(row.cardId)?.delete(row);\n      endIndex += 1;\n    }\n    while (startIndex < starts.length && finite(starts[startIndex].time) <= time + 1e-9) {\n      const row = starts[startIndex];\n      if (time < finite(row.end) - 1e-9) {\n        active.add(row);\n        activeByMember.get(row.cardId)?.add(row);\n      }\n      startIndex += 1;\n    }\n    const weight = scoring.weights[index] ?? 0;\n    const activePct = expectedMaximum(active);\n    const support = finite(fullSupportPct) + supportAt(windows, time);\n    const supportedPct = activePct * (1 + support / 100);\n    skillWeight += weight * (1 + supportedPct / 100);\n    for (const member of members) {\n      coverageAcc.set(member.id, coverageAcc.get(member.id) + probabilityAny(activeByMember.get(member.id) ?? []));\n    }\n  });\n\n  const details = members.map((member) => {\n    const memberChecks = checks.byMember.get(member.id) ?? [];\n    const expectedActivations = memberChecks.reduce((sum, row) => sum + row.probability, 0);\n    return {\n      cardId: member.id,\n      interval: member.active.interval,\n      duration: member.active.duration,\n      checks: memberChecks.length,\n      baseProbability: member.active.probability,\n      effectiveProbability: memberChecks.length\n        ? memberChecks.reduce((sum, row) => sum + row.probability, 0) / memberChecks.length\n        : 0,\n      expectedActivations,\n      coverage: notes.length ? coverageAcc.get(member.id) / notes.length : 0,\n      scoreUpPct: member.active.conditionalScoreUp || member.active.baseScoreUp,\n    };\n  });\n  const supportAveragePct = context.duration > 0\n    ? windows.reduce((sum, window) => sum + window.support * (window.end - window.start) / context.duration, 0)\n    : 0;\n  const activationRateAveragePct = context.duration > 0\n    ? windows.reduce((sum, window) => sum + window.activationRateUp * (window.end - window.start) / context.duration, 0)\n    : 0;\n  const skillMultiplier = scoring.baseWeight > 0 ? skillWeight / scoring.baseWeight : 1;\n  return {\n    skillMultiplier,\n    special: { supportAveragePct, activationRateAveragePct, windows },\n    details,\n    active: {\n      independentPct: Math.max(0, skillMultiplier - 1) * 100,\n      correctedPct: Math.max(0, skillMultiplier - 1) * 100,\n      duplicateGroups: 0,\n      collisionLossPct: 0,\n    },\n    checks: checks.all,\n  };\n}\n\n'''
text = text[:start] + replacement + text[end:]
start = text.index('export function timelineSongProjection({')
replacement = '''export function timelineSongProjection({\n  unitScore,\n  members,\n  context,\n  genericContext,\n  fullSupportPct,\n  playMode = "auto",\n  genericSkillMultiplier = 1,\n  scoreRules = null,\n  evaluationTarget = "both",\n}) {\n  const needExpected = evaluationTarget !== "potential";\n  const needMaximum = evaluationTarget !== "score";\n  const expected = needExpected\n    ? timelineSkillEvaluation(members, context, fullSupportPct, playMode, scoreRules, false)\n    : null;\n  const maximum = needMaximum\n    ? timelineSkillEvaluation(members, context, fullSupportPct, playMode, scoreRules, true)\n    : null;\n  const selectedKernel = songKernel(context, playMode, scoreRules);\n  const genericKernel = songKernel(genericContext, playMode, scoreRules);\n  const baseRatio = genericKernel > 0 ? selectedKernel / genericKernel : 1;\n  const skillRatio = expected && genericSkillMultiplier > 0 ? expected.skillMultiplier / genericSkillMultiplier : 1;\n  const maxSkillRatio = maximum && genericSkillMultiplier > 0 ? maximum.skillMultiplier / genericSkillMultiplier : 1;\n  const averageScore = expected ? Math.max(0, Math.round(unitScore * baseRatio * skillRatio)) : null;\n  const rawMaxScore = maximum ? Math.max(0, Math.round(unitScore * baseRatio * maxSkillRatio)) : null;\n  const maxScore = rawMaxScore == null ? null : Math.max(averageScore ?? 0, rawMaxScore);\n  return {\n    averageScore,\n    maxScore,\n    baseRatio,\n    skillRatio,\n    maxSkillRatio,\n    context,\n    playMode: playMode === "manual" ? "manual" : "auto",\n    expected,\n    maximum,\n    specialWindows: expected?.special?.windows ?? maximum?.special?.windows ?? [],\n    note: "실제 채보의 노트 시각/종류와 SP 슬롯 발동 시각을 사용합니다.",\n  };\n}\n'''
text = text[:start] + replacement
p.write_text(text, encoding='utf-8')

